      <symbol id="i-gauge" viewBox="0 0 24 24"><path d="M4.9 19a9 9 0 1 1 14.2 0H4.9Z"/><path d="m12 13 4-5M5 12H3m18 0h-2M12 5V3"/><circle cx="12" cy="13" r="1"/></symbol>
